/** Round-cue phrase rotation (in-memory; resets with the page). */
let phraseCursor = 0;

/** Next rotating round phrase. */
export function nextAutoplayPhraseBase64(): string {
  const phrase = AUTOPLAY_PHRASE_MP3_BASE64S[phraseCursor % AUTOPLAY_PHRASE_MP3_BASE64S.length]!;
  phraseCursor += 1;
  return phrase;
}

/** Test hook: restart the phrase rotation. */
export function resetAutoplayPhraseRotation(): void {
  phraseCursor = 0;
  }
